parameters.jsCode:
/**
 * Node 1b · Normalise the Trigify payload.
 *
 * Trigify signals are user-composed in the HTTP Request action, so the payload
 * shape is not fixed. Rather than pin one schema, read every field through a
 * fallback chain and report exactly what is missing. Nothing here throws: a bad
 * signal is routed to the "skipped" response, not an execution error, so a
 * malformed webhook never shows up as a red run.
 */
const incoming = $input.first().json;
const body = incoming.body ?? incoming;
const headers = incoming.headers ?? {};

const pick = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    const text = typeof value === 'string' ? value.trim() : value;
    if (text !== '' && text !== 'null' && text !== 'undefined') return text;
  }
  return null;
};

const asObject = (value, key = 'name') => {
  if (!value) return {};
  if (typeof value === 'string') return { [key]: value };
  return typeof value === 'object' ? value : {};
};

const normaliseDomain = (value) => {
  if (!value) return null;
  return String(value).trim().toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .split(/[/?#]/)[0]
    .replace(/\.$/, '') || null;
};

// --- shared-secret gate ----------------------------------------------------
const expectedSecret = $env.TRIGIFY_WEBHOOK_SECRET || '';
const presentedSecret = headers['x-webhook-secret'] || headers['x-trigify-secret'] || '';
if (expectedSecret && presentedSecret !== expectedSecret) {
  return [{ json: { valid: false, stage: 'auth', reason: 'x-webhook-secret did not match TRIGIFY_WEBHOOK_SECRET' } }];
}

// --- locate the three sub-objects Trigify may or may not nest ---------------
const person = asObject(body.prospect || body.lead || body.person || body.contact || body);
const company = asObject(body.company || body.organization || person.company || person.organization, 'name');
const signal = asObject(body.signal || body.trigger || body.event || body, 'type');

const firstName = pick(person.first_name, person.firstName, person.given_name);
const lastName = pick(person.last_name, person.lastName, person.family_name);
const fullName = pick(
  person.full_name, person.fullName, person.name,
  firstName && lastName ? `${firstName} ${lastName}` : null,
);

const companyDomain = normaliseDomain(pick(
  company.domain, company.company_domain, company.website, company.url,
  person.company_domain, person.domain, body.domain, body.company_domain,
));

const companyName = pick(
  company.name, company.company_name, company.title,
  person.company_name, body.company_name,
);

// --- describe the signal in one readable line for the copywriter ------------
const signalType = pick(
  signal.type, signal.signal_type, signal.event_type, signal.name,
  body.signal_type, body.event, body.trigger_type,
) || 'custom_signal';

const signalText = pick(
  signal.post_content, signal.content, signal.comment, signal.comment_text,
  signal.text, signal.message, signal.description, signal.summary,
  body.post_content, body.comment,
);
const signalKeyword = pick(signal.keyword, signal.keywords, signal.search_term, body.keyword);
const signalSource = pick(signal.source_url, signal.url, signal.post_url, signal.permalink, body.source_url);
const signalActor = pick(signal.target_name, signal.competitor, signal.group_name, signal.author, body.target);

const signalContext = [
  signalActor ? `Target/context: ${signalActor}.` : null,
  signalKeyword ? `Matched keyword: ${Array.isArray(signalKeyword) ? signalKeyword.join(', ') : signalKeyword}.` : null,
  signalText ? `What they wrote or did: "${String(signalText).replace(/\s+/g, ' ').slice(0, 600)}"` : null,
  signalSource ? `Source: ${signalSource}` : null,
].filter(Boolean).join(' ') || 'No context text was supplied with this signal.';

const techStack = (() => {
  const raw = company.tech_stack || company.technologies || person.tech_stack || body.tech_stack;
  if (!raw) return [];
  if (Array.isArray(raw)) return raw.filter(Boolean).map(String);
  return String(raw).split(/[,;|]/).map((s) => s.trim()).filter(Boolean);
})();

const employeeCount = Number(pick(
  company.employee_count, company.employees, company.size, company.headcount,
  body.employee_count,
));

const lead = {
  signal_id: pick(signal.id, signal.signal_id, body.id, body.event_id),
  received_at: new Date().toISOString(),

  full_name: fullName,
  first_name: firstName || (fullName ? String(fullName).split(' ')[0] : null),
  last_name: lastName,
  job_title: pick(person.job_title, person.title, person.position, person.headline, person.role),
  linkedin_url: pick(person.linkedin_url, person.linkedinUrl, person.profile_url, person.linkedin, body.linkedin_url),
  provided_email: pick(person.email, person.work_email, body.email),

  company_name: companyName,
  company_domain: companyDomain,
  company_description: pick(
    company.description, company.about, company.summary, company.short_description,
    body.company_description,
  ),
  industry: pick(company.industry, company.sector, person.industry, body.industry),
  employee_count: Number.isFinite(employeeCount) && employeeCount > 0 ? employeeCount : null,
  tech_stack: techStack,

  signal_type: signalType,
  signal_context: signalContext,
  signal_url: signalSource,
  signal_timestamp: pick(signal.timestamp, signal.created_at, signal.occurred_at, body.timestamp),

  raw_payload: body,
};

const missing = [];
if (!lead.full_name) missing.push('full_name');
if (!lead.company_domain && !lead.company_name) missing.push('company_domain or company_name');

return [{
  json: {
    ...lead,
    valid: missing.length === 0,
    stage: 'normalise',
    reason: missing.length ? `Signal is missing required field(s): ${missing.join(', ')}` : null,
  },
}];

/**
 * Node 2b · Pick the address to verify.
 *
 * Findymail returns { contact: { email, ... } } on a hit and a 4xx body on a
 * miss. The HTTP node runs with neverError so a miss lands here as data, which
 * lets us fall back to an address Trigify already carried rather than dropping
 * an otherwise good signal.
 */
const lead = $('Node 1b · Normalise Signal').first().json;
const response = $input.first().json ?? {};
const contact = response.contact || response.data?.contact || null;

const findymailEmail = contact?.email ? String(contact.email).trim().toLowerCase() : null;
const fallbackEmail = lead.provided_email ? String(lead.provided_email).trim().toLowerCase() : null;
const candidate = findymailEmail || fallbackEmail;

const apiError = !findymailEmail
  ? (response.error || response.message || (response.status ? `HTTP ${response.status}` : null))
  : null;

return [{
  json: {
    ...lead,
    stage: 'discovery',
    candidate_email: candidate,
    email_source: findymailEmail ? 'findymail' : (fallbackEmail ? 'trigify_payload' : null),
    email_found: Boolean(candidate),
    // Findymail often knows more about the person than the signal did.
    job_title: lead.job_title || contact?.position || contact?.job_title || null,
    company_name: lead.company_name || contact?.company || null,
    company_domain: lead.company_domain || contact?.domain || null,
    linkedin_url: lead.linkedin_url || contact?.linkedin_url || null,
    findymail_raw: contact,
    reason: candidate ? null : `No email found for ${lead.full_name} at ${lead.company_domain || lead.company_name}${apiError ? ` (Findymail said: ${apiError})` : ''}`,
  },
}];

/**
 * Node 2c · Reputation guard.
 *
 * Findymail's /verify returns { email, verified, provider }. Anything that is
 * not an unambiguous verified:true is dropped — a catch-all domain accepts every
 * address at SMTP time and then bounces later, which is exactly the failure that
 * burns a warmed inbox pool. Role addresses are dropped too: they are shared
 * inboxes, they read as spam traffic, and they never reply to peer-to-peer copy.
 */
const lead = $('Node 2b · Select Candidate Email').first().json;
const result = $input.first().json ?? {};

const email = String(result.email || lead.candidate_email || '').trim().toLowerCase();
const localPart = email.split('@')[0] || '';
const domain = email.split('@')[1] || '';

const ROLE_PREFIXES = new Set([
  'info', 'support', 'sales', 'hello', 'contact', 'admin', 'billing', 'noreply',
  'no-reply', 'help', 'team', 'office', 'press', 'legal', 'privacy', 'abuse',
  'postmaster', 'webmaster', 'careers', 'jobs', 'marketing', 'enquiries', 'mail',
]);

const FREE_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com', 'outlook.com',
  'icloud.com', 'aol.com', 'proton.me', 'protonmail.com', 'live.com', 'msn.com',
  'gmx.com', 'yandex.com', 'mail.com', 'zoho.com',
]);

const rejections = [];

// Findymail flags a catch-all / risky address by NOT returning verified:true.
// Treat a missing field as unverified rather than assuming the best.
if (result.verified !== true) {
  rejections.push(`Findymail did not verify the address (verified=${JSON.stringify(result.verified ?? null)})`);
}
// Some accounts surface these extra hints; honour them when present.
if (result.risky === true) rejections.push('Findymail marked the address risky');
if (result.catch_all === true || result.catchAll === true) rejections.push('domain is catch-all');
if (result.disposable === true) rejections.push('disposable domain');

if (!email.includes('@')) rejections.push('no usable address to verify');
if (ROLE_PREFIXES.has(localPart)) rejections.push(`role address (${localPart}@)`);
if (FREE_DOMAINS.has(domain)) rejections.push(`free consumer mailbox (${domain})`);

return [{
  json: {
    ...lead,
    stage: 'verification',
    lead_email: email || null,
    email_provider: result.provider || null,
    email_verified: result.verified === true,
    deliverable: rejections.length === 0,
    reason: rejections.length ? `Suppressed to protect sender reputation: ${rejections.join('; ')}` : null,
    findymail_verify_raw: result,
  },
}];

