/**
 * Node 4a · Render config.json + the learning corpus into prompt blocks.
 *
 * Everything the agent reasons over is assembled here, so the system prompt in
 * the next node stays a fixed set of rules and the volatile per-lead data rides
 * in the user message. Edit config.json and the blocks below change on the next
 * signal with no workflow change.
 */
const context = $input.first().json;
const lead = $('Node 2c · Filter Risky Emails').first().json;
const config = context.config || {};

const offer = config.offer || {};
const icp = config.icp || {};
const disq = config.disqualifiers || {};
const copy = config.copywriting || {};
const campaign = config.campaign || {};

const list = (values, fallback = 'not specified') =>
  Array.isArray(values) && values.length ? values.join(', ') : fallback;

const bullets = (values) =>
  Array.isArray(values) && values.length ? values.map((v) => `- ${v}`).join('\n') : '- (none)';

const offerBlock = [
  `Product: ${offer.product || 'unnamed product'}`,
  `What it does: ${offer.what_it_does || 'not specified'}`,
  `The frictionless offer (this is sentence 2, restate it in your own words, do not quote it verbatim): ${offer.frictionless_offer}`,
  offer.proof_point ? `Optional proof point you may draw on: ${offer.proof_point}` : null,
  `The CTA (this is sentence 3): ${offer.cta}`,
  campaign.sender_name ? `You are writing as: ${campaign.sender_name}${campaign.sender_title ? `, ${campaign.sender_title}` : ''}` : null,
].filter(Boolean).join('\n');

const icpBlock = [
  `Target job titles: ${list(icp.job_titles)}`,
  `Target seniority: ${list(icp.seniority)}`,
  `Target industries: ${list(icp.industries)}`,
  `Target geographies: ${list(icp.geos)}`,
  `Headcount band: ${icp.employee_count?.min ?? '?'} to ${icp.employee_count?.max ?? '?'} employees`,
  `Tech-stack signals that indicate fit: ${list(icp.tech_stack_signals)}`,
  icp.notes ? `Notes: ${icp.notes}` : null,
].filter(Boolean).join('\n');

const disqualifierBlock = [
  'Hard disqualifiers (already checked deterministically before you were called — re-check anything the data now contradicts):',
  `- job titles containing: ${list(disq.hard?.job_title_contains, 'none')}`,
  `- company names containing: ${list(disq.hard?.company_name_contains, 'none')}`,
  `- industries: ${list(disq.hard?.industries, 'none')}`,
  `- headcount outside ${disq.hard?.employee_count?.min ?? '?'}–${disq.hard?.employee_count?.max ?? '?'}`,
  '',
  'Judgement-call disqualifiers (yours to apply — this is the part the deterministic check cannot do):',
  bullets(disq.soft_notes),
].join('\n');

const copyRulesBlock = [
  `Hard limits: exactly ${copy.sentence_count ?? 3} sentences, ${copy.max_words ?? 60} words maximum across the whole body.`,
  `Tone: ${copy.tone || 'peer-to-peer, plain'}`,
  '',
  'Rules:',
  bullets(copy.rules),
  '',
  'Banned phrases — if any of these appear in your draft, rewrite the sentence:',
  bullets(copy.banned_phrases),
].join('\n');

const leadBlock = [
  `Name: ${lead.full_name}`,
  `Job title: ${lead.job_title || 'unknown'}`,
  `Company: ${lead.company_name || 'unknown'}${lead.company_domain ? ` (${lead.company_domain})` : ''}`,
  `Industry: ${lead.industry || 'unknown'}`,
  `Headcount: ${lead.employee_count || 'unknown'}`,
  `Tech stack: ${list(lead.tech_stack, 'unknown')}`,
  `Company description: ${lead.company_description || 'not supplied by the signal source'}`,
  `Verified work email: ${lead.lead_email} (provider: ${lead.email_provider || 'unknown'})`,
  lead.linkedin_url ? `LinkedIn: ${lead.linkedin_url}` : null,
].filter(Boolean).join('\n');

const signalBlock = [
  `Signal type: ${lead.signal_type}`,
  `Recognised signal type: ${(config.signal?.allowed_types || []).includes(lead.signal_type) ? 'yes' : 'NO — treat this signal conservatively, it is outside the configured set'}`,
  `Signal context: ${lead.signal_context}`,
  lead.signal_timestamp ? `Signal fired at: ${lead.signal_timestamp}` : null,
].filter(Boolean).join('\n');

const conversionCount = Number(context.conversion_count || 0);
const gateEnforced = context.lookalike_gate_enforced === true;
const pastReplies = context.past_positive_replies_list || '';

const lookalikeBlock = pastReplies
  ? [
      `We have ${conversionCount} recorded positive reply/replies. The ${context.conversions_returned} most recent profiles are below.`,
      gateEnforced
        ? 'The lookalike gate is ENFORCED: the prospect must conceptually resemble at least one of these wins, and you must name which one and why.'
        : `The lookalike gate is ADVISORY: fewer than ${config.learning?.lookalike_enforced_after_n_conversions ?? 3} conversions is not enough signal to pattern-match on, so judge against the ICP block and use these only as a tie-breaker.`,
      '',
      pastReplies,
    ].join('\n')
  : 'There are no recorded positive replies yet. The lookalike gate does not apply — qualify against the ICP block alone, and say so in your reason.';

const agentInput = [
  '## PROSPECT', leadBlock, '',
  '## THE TRIGIFY SIGNAL THAT FIRED', signalBlock, '',
  '## PAST POSITIVE REPLIES (our wins, newest first)', lookalikeBlock, '',
  '## YOUR TASK',
  gateEnforced
    ? 'Run the lookalike gate against the wins above, then, only if it passes, write the email.'
    : 'Run the qualification gate against the ICP, then, only if it passes, write the email.',
].join('\n');

return [{
  json: {
    ...lead,
    stage: 'agent',
    product_name: offer.product || 'this product',
    offer_block: offerBlock,
    icp_block: icpBlock,
    disqualifier_block: disqualifierBlock,
    copy_rules_block: copyRulesBlock,
    lookalike_gate_enforced: gateEnforced,
    conversion_count: conversionCount,
    past_positive_replies_list: pastReplies,
    agent_input: agentInput,
  },
}];

