parameters.jsCode:
/**
 * Every rejection path lands here so the webhook caller gets one consistent
 * shape instead of whatever the failing node happened to be holding.
 */
const item = $input.first().json ?? {};

const hard = item.hard_disqualifier;
const reason = item.reason
  || (hard?.hit ? `Hard disqualifier: ${(hard.rules || []).join('; ')}` : null)
  || (item.already_contacted ? 'Already contacted — suppressed by outreach_log' : null)
  || 'Skipped without a stated reason';

return [{
  json: {
    status: 'skipped',
    stage: item.stage || (hard ? 'guardrails' : 'unknown'),
    reason,
    qualified: item.qualified === true ? true : false,
    lead: {
      full_name: item.full_name ?? null,
      lead_email: item.lead_email ?? item.candidate_email ?? null,
      company_name: item.company_name ?? null,
      company_domain: item.company_domain ?? null,
      signal_type: item.signal_type ?? null,
    },
    at: new Date().toISOString(),
  },
}];

/**
 * Node 6a · Decide whether an inbound Deliveryman event is a positive reply.
 *
 * Only a positive reply may write to campaign_memory.db. A bounce, an
 * out-of-office or an unsubscribe written into the conversions table would
 * poison the lookalike context for every future lead, so the test is an
 * allow-list, never a "not negative" test.
 */
const incoming = $input.first().json;
const body = incoming.body ?? incoming;
const headers = incoming.headers ?? {};

const expectedSecret = $env.DELIVERYMAN_WEBHOOK_SECRET || '';
const presentedSecret = headers['x-webhook-secret'] || headers['x-deliveryman-secret'] || '';
if (expectedSecret && presentedSecret !== expectedSecret) {
  return [{ json: { positive: false, reason: 'x-webhook-secret did not match DELIVERYMAN_WEBHOOK_SECRET' } }];
}

const lower = (v) => String(v ?? '').trim().toLowerCase();

const eventType = lower(body.event || body.event_type || body.type || body.status);
const sentiment = lower(body.sentiment || body.interest_status || body.label || body.category || body.classification);
const replyText = body.reply_text || body.text || body.message || body.body || body.snippet || '';

const NEGATIVE_EVENTS = ['bounce', 'bounced', 'hard_bounce', 'soft_bounce', 'complaint', 'spam', 'unsubscribe', 'unsubscribed', 'auto_reply', 'out_of_office'];
const POSITIVE_SENTIMENTS = ['positive', 'interested', 'interest', 'meeting_booked', 'meeting', 'hot', 'warm'];
const REPLY_EVENTS = ['reply', 'replied', 'email_replied', 'reply_received', 'positive_reply', 'lead_interested', 'interested'];

const isNegativeEvent = NEGATIVE_EVENTS.some((e) => eventType.includes(e));
const isReplyEvent = REPLY_EVENTS.some((e) => eventType.includes(e)) || Boolean(replyText);
const isPositiveSentiment = POSITIVE_SENTIMENTS.some((s) => sentiment === s || sentiment.includes(s));

// An explicit positive label from Deliveryman is the trusted path. The event
// name alone is only trusted when the event itself says "positive"/"interested",
// because a bare "reply" can be "please remove me".
const positive = !isNegativeEvent && isReplyEvent && (
  isPositiveSentiment ||
  eventType.includes('positive') ||
  eventType.includes('interested')
);

// Metadata we attached at send time, if Deliveryman echoed it back. Anything
// missing is backfilled server-side from outreach_log.
const meta = body.metadata || body.custom_variables || body.variables || body.lead || {};

const email = lower(
  body.lead_email || body.email || body.to || body.to_email ||
  body.recipient || meta.lead_email || ''
) || null;

return [{
  json: {
    positive,
    reason: positive ? 'Positive reply registered' : `Not recorded as a conversion (event="${eventType || 'unknown'}", sentiment="${sentiment || 'none'}")`,
    event_type: eventType || null,
    sentiment: sentiment || null,
    lead_email: email,
    full_name: body.full_name || meta.full_name || null,
    job_title: body.job_title || meta.job_title || null,
    company_name: body.company_name || meta.company_name || null,
    company_domain: body.company_domain || meta.company_domain || null,
    company_description: body.company_description || meta.company_description || null,
    tech_stack: meta.tech_stack || body.tech_stack || null,
    employee_count: meta.employee_count ?? body.employee_count ?? null,
    signal_type: meta.signal_type || body.signal_type || null,
    signal_context: meta.signal_context || body.signal_context || null,
    reply_snippet: replyText ? String(replyText).replace(/\s+/g, ' ').slice(0, 500) : null,
    raw_payload: body,
  },
}];

